import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        int[] l = new int[n];
        for (int i = 0; i < n; i++) {
            l[i] = Integer.parseInt(st.nextToken());
        }
        int lenPart1 = n / 2;
        int lenPart2 = n - lenPart1;
        int[] part1 = Arrays.copyOfRange(l, 0, lenPart1);
        int[] part2 = Arrays.copyOfRange(l, lenPart1, n);
        int count1 = 1 << lenPart1;
        int count2 = 1 << lenPart2;

        List<Integer> sums1 = new ArrayList<>();
        for (int mask = 0; mask < count1; mask++) {
            int total = 0;
            for (int idx = 0; idx < lenPart1; idx++) {
                if ((mask & (1 << idx)) != 0) {
                    total += part1[idx];
                }
            }
            sums1.add(total % m);
        }

        List<Integer> sums2 = new ArrayList<>();
        for (int mask = 0; mask < count2; mask++) {
            int total = 0;
            for (int idx = 0; idx < lenPart2; idx++) {
                if ((mask & (1 << idx)) != 0) {
                    total += part2[idx];
                }
            }
            sums2.add(total % m);
        }

        Collections.sort(sums1);
        Collections.sort(sums2);

        int maxResult = 0;

        for (int s : sums1) {
            int req = m - s;
            int val = binarySearchMax(sums2, req);
            maxResult = Math.max(maxResult, (s + val) % m);
        }

        System.out.println(maxResult);
    }

    private static int binarySearchMax(List<Integer> list, int x) {
        int low = 0;
        int high = list.size() - 1;
        int ans = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < x) {
                ans = list.get(mid);
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}
